<template><section class="staking-period-editor"><h3>{{ $t('Staking periods and returns') }}</h3><p>{{ $t('APR = period return × 365 ÷ days. Simple annualization, without compounding.') }}</p><label>{{ $t('Example principal') }} <input v-model="principal" type="number" min="0" step="any"></label><div class="period-scroll"><table><thead><tr><th>{{ $t('Days') }}</th><th>{{ $t('Period return (%)') }}</th><th>{{ $t('APR (%)') }}</th><th>{{ $t('Estimated period reward') }}</th><th></th></tr></thead><tbody><tr v-for="(p,i) in periods" :key="i"><td><input :value="p.days" @input="update(i,'days',$event.target.value)" type="number" min="1" step="1" :aria-label="$t('Days')"></td><td><input :value="p.rate" @input="update(i,'rate',$event.target.value)" type="number" min="0" step="any" :aria-label="$t('Period return (%)')"></td><td><input :value="apr(p)" @change="update(i,'rate',(Number($event.target.value)*Number(p.days)/365).toFixed(14).replace(/\.?0+$/,'') || '0')" type="number" min="0" step="any" :aria-label="$t('APR (%)')"></td><td>{{ reward(p) }}</td><td><button type="button" @click="remove(i)" :disabled="periods.length===1">{{ $t('Remove') }}</button></td></tr></tbody></table></div><button type="button" @click="add" :disabled="periods.length>=20">+ {{ $t('Add period') }}</button></section></template>
<script>
import {annualizedRate} from '@/Functions/UserDisplay.mjs';
export default {props:['days','rates'],data:()=>({principal:'1000'}),computed:{periods(){const days=String(this.days??'').split(','),rates=String(this.rates??'').split(',');return days.map((d,i)=>({days:d.trim(),rate:rates[i]?.trim()??''}))}},methods:{apr:p=>annualizedRate(p.rate,p.days),reward(p){const n=Number(this.principal)*Number(p.rate)/100;return Number.isFinite(n)?n.toLocaleString('en-US',{maximumFractionDigits:8}):'—'},emit(rows){this.$emit('change',{days:rows.map(p=>p.days).join(','),rates:rows.map(p=>p.rate).join(',')})},update(i,k,v){const rows=this.periods;rows[i][k]=v;this.emit(rows)},remove(i){this.emit(this.periods.filter((_,n)=>n!==i))},add(){this.emit([...this.periods,{days:'',rate:''}])}}}
</script>
<style scoped>.staking-period-editor{padding:16px;background:#f8fafc;border:1px solid #dbe2ea;border-radius:12px}.staking-period-editor h3{font-weight:700}.staking-period-editor p{margin:8px 0;color:#526071}.staking-period-editor input{max-width:135px;padding:7px;border:1px solid #cbd5e1;border-radius:6px}.staking-period-editor th,.staking-period-editor td{padding:8px;text-align:left;white-space:nowrap}.period-scroll{overflow:auto;margin:12px 0}.staking-period-editor button{color:#1d6350;padding:8px}</style>
